import React from 'react';

function AquariumList({ aquariums }) {
    if (!aquariums || aquariums.length === 0) {
        return <p style={{color:'#888', marginTop:'24px'}}>No aquariums yet. Add one!</p>;
    }

    return (
        <div>
            <h3 style={{color:'#2563eb', marginBottom:'18px'}}>My Aquariums</h3>
            {aquariums.map(aq => (
                <div key={aq.id} className="card-aquarium">
                    {aq.photoUrl && <img src={aq.photoUrl} alt={aq.name} onError={e => e.target.style.display='none'} />}
                    <div className="card-aquarium-details" style={{textAlign:'left', width:'100%'}}>
                        <h4>{aq.name}</h4>
                        <p><strong>Volumen:</strong> {aq.volume} L</p>
                        <p><strong>Tipo:</strong> {aq.type}</p>
                        {aq.targetParameters && <p><strong>Parámetros:</strong> {aq.targetParameters}</p>}
                        {aq.initialSetupNotes && <p><strong>Notas:</strong> {aq.initialSetupNotes}</p>}
                    </div>
                </div>
            ))}
        </div>
    );
}

export default AquariumList;
